CREATE OR REPLACE FUNCTION public.activity_post_search_text(body jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
  select coalesce(string_agg(part, ' '), '')
  from (
    select case b.value->>'type'
      when 'text' then b.value->>'text'
      when 'mod' then concat_ws(' ', b.value->>'label', b.value->>'detail')
      when 'performance' then b.value->>'note'
      else null
    end as part
    from jsonb_array_elements(
      case when jsonb_typeof(body) = 'array' then body else '[]'::jsonb end
    ) as b
  ) parts
  where part is not null and part <> ''
$function$;

grant execute on function public.activity_post_search_text(body jsonb) to anon;
grant execute on function public.activity_post_search_text(body jsonb) to authenticated;
grant execute on function public.activity_post_search_text(body jsonb) to public;
grant execute on function public.activity_post_search_text(body jsonb) to service_role;
